// --- Cricket Types ---

export type CricketTarget = 20 | 19 | 18 | 17 | 16 | 15 | 25;

export interface CricketPlayerState {
    id: string;
    name: string;
    score: number;
    marks: Record<CricketTarget, number>; // 0 to 3
    dartsThrown: number;
    history: {
        target: CricketTarget | null;
        multiplier: 1 | 2 | 3;
        isMiss: boolean;
        pointsScored: number;
    }[];
}

import { CricketPlayerState, CricketTarget, Player } from '../types';

export const CRICKET_TARGETS: CricketTarget[] = [20, 19, 18, 17, 16, 15, 25];

export const initCricketState = (players: Player[]): CricketPlayerState[] => {
    return players.map(p => ({
        id: p.id,
        name: p.name,
        score: 0,
        marks: {
            20: 0, 19: 0, 18: 0, 17: 0, 16: 0, 15: 0, 25: 0
        },
        dartsThrown: 0,
        history: []
    }));
};

export const isNumberClosedGlobally = (states: CricketPlayerState[], target: CricketTarget): boolean => {
    // A number is closed globally if ALL players have 3 marks on it
    return states.every(p => p.marks[target] >= 3);
};

export const processCricketHit = (
    states: CricketPlayerState[],
    playerId: string,
    target: CricketTarget,
    multiplier: 1 | 2 | 3
): { newStates: CricketPlayerState[], pointsScored: number, isClosedByHit: boolean } => {

    const pIdx = states.findIndex(p => p.id === playerId);
    if (pIdx === -1) return { newStates: states, pointsScored: 0, isClosedByHit: false };

    // Deep copy to avoid mutation
    const newStates = JSON.parse(JSON.stringify(states));
    const player = newStates[pIdx];

    const currentMarks = player.marks[target];
    const newTotalMarks = currentMarks + multiplier;

    let pointsScored = 0;
    let marksToAdd = multiplier;
    let isClosedByHit = false;

    // Logic:
    // 1. Fill marks up to 3.
    // 2. If > 3, check if opponents have closed it.
    // 3. If opponents NOT closed, add (surplus * targetValue) to score.

    if (currentMarks < 3) {
        const needed = 3 - currentMarks;
        if (multiplier >= needed) {
            // We closed it this turn
            player.marks[target] = 3;
            marksToAdd = multiplier - needed; // Remaining marks for scoring
            isClosedByHit = true;
        } else {
            // Just adding marks, not closed yet
            player.marks[target] += multiplier;
            marksToAdd = 0; 
        }
    } else {
        // Already closed by player, all multiplier is for potential scoring
        marksToAdd = multiplier;
    }

    // Scoring Logic (Strict Rules)
    // Points are scored if the player has closed the number (which is true if marksToAdd > 0 here)
    // AND at least one opponent has NOT closed it.
    if (marksToAdd > 0) {
        const isClosedByAll = newStates.every((p: CricketPlayerState) => p.marks[target] >= 3);

        if (!isClosedByAll) {
            pointsScored = marksToAdd * target;
            player.score += pointsScored;
        }
    }

    player.dartsThrown += 1;
    player.history.push({
        target,
        multiplier,
        isMiss: false,
        pointsScored
    });

    return { newStates, pointsScored, isClosedByHit };
};

export const checkCricketWin = (states: CricketPlayerState[]): string | null => {
    // Win condition:
    // 1. Player has closed all numbers (all marks >= 3)
    // 2. Player has the highest (or tied highest) score

    // Sort by score descending to easily check lead
    const sortedByScore = [...states].sort((a,b) => b.score - a.score);
    const highestScore = sortedByScore[0].score;

    for (const player of states) {
        const allClosed = CRICKET_TARGETS.every(t => player.marks[t] >= 3);
        const hasScoreLead = player.score >= highestScore;

        if (allClosed && hasScoreLead) {
            return player.id;
        }
    }

    return null;
};

import React from 'react';
import { CricketPlayerState, CricketTarget } from '../../types';
import { CRICKET_TARGETS } from '../../utils/cricketLogic';

interface CricketScoreboardProps {
    players: CricketPlayerState[];
    currentPlayerId: string;
}

export const CricketScoreboard: React.FC<CricketScoreboardProps> = ({ players, currentPlayerId }) => {

    // Determine column grid based on player count (supports 2 to 4)
    const gridCols = players.length === 2 ? 'grid-cols-[1fr_60px_1fr]' 
                   : players.length === 3 ? 'grid-cols-[1fr_60px_1fr_1fr]'
                   : 'grid-cols-[1fr_60px_1fr_1fr_1fr]'; // 4 players

    // Helper to render mark symbol
    const renderMark = (count: number, isClosedByAll: boolean) => {
        let content = null;
        if (count === 0) content = <span className="opacity-0">.</span>;
        else if (count === 1) content = <span className="text-3xl font-sans">/</span>;
        else if (count === 2) content = <span className="text-3xl font-sans">X</span>;
        else if (count >= 3) content = (
            <div className="relative flex items-center justify-center w-8 h-8">
                 <span className="absolute text-3xl font-sans">X</span>
                 <div className="absolute inset-0 rounded-full border-2 border-current"></div>
            </div>
        );

        return (
            <div className={`flex items-center justify-center w-full h-full font-black transition-all duration-300 ${
                isClosedByAll ? 'text-gray-700' : 
                count >= 3 ? 'text-green-500 shadow-[0_0_10px_rgba(34,197,94,0.4)]' : 
                'text-white'
            }`}>
                {content}
            </div>
        );
    };

    return (
        <div className="flex-1 flex flex-col w-full h-full bg-black/40 backdrop-blur-sm p-1 md:p-4 overflow-hidden">

            {/* Header: Player Names & Scores */}
            <div className={`grid ${gridCols} gap-1 mb-2 shrink-0`}>
                {players.map((p, idx) => (
                    <div 
                        key={p.id} 
                        className={`
                            flex flex-col items-center justify-center p-2 rounded-t-lg border-b-4 transition-all
                            ${idx % 2 !== 0 && players.length === 2 ? 'order-3' : ''} 
                            ${p.id === currentPlayerId 
                                ? 'bg-gray-800 border-orange-500 shadow-[0_0_15px_rgba(234,88,12,0.3)]' 
                                : 'bg-gray-900/50 border-gray-700 opacity-70'}
                        `}
                    >
                        <div className={`text-[10px] md:text-sm font-bold uppercase truncate max-w-full ${p.id === currentPlayerId ? 'text-orange-500' : 'text-gray-400'}`}>
                            {p.name}
                        </div>
                        <div className="text-2xl md:text-4xl font-mono font-black text-white mt-1">
                            {p.score}
                        </div>
                    </div>
                ))}

                {/* Center Column Header (Hidden on mobile usually, or just filler) */}
                {players.length === 2 && <div className="order-2"></div>}
            </div>

            {/* The Grid */}
            <div className="flex-1 overflow-y-auto custom-scrollbar">
                {CRICKET_TARGETS.map((target) => {
                    const isClosedByAll = players.every(p => p.marks[target] >= 3);

                    return (
                        <div key={target} className={`grid ${gridCols} gap-1 mb-1 min-h-[50px]`}>

                             {/* Player 1 Marks */}
                             <div className={`bg-gray-800/40 rounded flex items-center justify-center border ${players[0].id === currentPlayerId ? 'border-gray-700' : 'border-transparent'}`}>
                                 {renderMark(players[0].marks[target], isClosedByAll)}
                             </div>

                             {/* Target Label */}
                             {players.length === 2 ? (
                                 <div className="order-2 flex items-center justify-center bg-gray-900 rounded border border-gray-800">
                                     <span className={`font-black text-xl md:text-2xl ${isClosedByAll ? 'text-gray-700 line-through decoration-2' : 'text-orange-500'}`}>
                                         {target === 25 ? 'B' : target}
                                     </span>
                                 </div>
                             ) : null}

                             {/* Other Players */}
                             {players.slice(1).map((p, idx) => (
                                 <div key={p.id} className={`bg-gray-800/40 rounded flex items-center justify-center border ${p.id === currentPlayerId ? 'border-gray-700' : 'border-transparent'} ${players.length === 2 ? 'order-3' : ''}`}>
                                     {renderMark(p.marks[target], isClosedByAll)}
                                 </div>
                             ))}
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

