import React, { useState, useEffect } from 'react';
import { Player, CricketPlayerState, CricketTarget } from '../types';
import { initCricketState, processCricketHit, checkCricketWin } from '../utils/cricketLogic';
import { CricketScoreboard } from '../components/game/CricketScoreboard';
import { CricketKeypad } from '../components/game/CricketKeypad';
import { Button } from '../components/ui/Button';

interface CricketGameViewProps {
    players: Player[];
    onExit: () => void;
    onFinish: (results: CricketPlayerState[]) => void;
}

export const CricketGameView: React.FC<CricketGameViewProps> = ({ players, onExit, onFinish }) => {
    const [states, setStates] = useState<CricketPlayerState[]>(() => initCricketState(players));
    const [currentPlayerIdx, setCurrentPlayerIdx] = useState(0);
    const [turnDartsThrown, setTurnDartsThrown] = useState(0);
    const [history, setHistory] = useState<CricketPlayerState[][]>([]); // Undo history (full state snapshots)
    const [showExitConfirm, setShowExitConfirm] = useState(false);
    const [winnerId, setWinnerId] = useState<string | null>(null);

    const currentPlayer = states[currentPlayerIdx];

    const handleHit = (target: CricketTarget, multiplier: 1 | 2 | 3) => {
        if (winnerId) return;

        // Save state for undo
        setHistory(prev => [...prev, JSON.parse(JSON.stringify(states))]);

        // Process Hit
        const result = processCricketHit(states, currentPlayer.id, target, multiplier);
        setStates(result.newStates);

        // Check Win
        const win = checkCricketWin(result.newStates);
        if (win) {
            setWinnerId(win);
            return;
        }

        advanceTurn();
    };

    const handleMiss = () => {
        if (winnerId) return;
        setHistory(prev => [...prev, JSON.parse(JSON.stringify(states))]);

        // Just update darts thrown
        setStates(prev => {
            const copy = [...prev];
            copy[currentPlayerIdx].dartsThrown += 1;
            copy[currentPlayerIdx].history.push({ target: null, multiplier: 1, isMiss: true, pointsScored: 0 });
            return copy;
        });

        advanceTurn();
    };

    const advanceTurn = () => {
        const nextDartsThrown = turnDartsThrown + 1;

        if (nextDartsThrown >= 3) {
            // Delay for visual effect
            setTimeout(() => {
                setTurnDartsThrown(0);
                setCurrentPlayerIdx(prev => (prev + 1) % players.length);
                // Clear undo history between turns? Usually yes for cleaner UI, 
                // but for now we keep local turn history in 'states'. 
                // The 'history' state variable tracks full match states for deep undo if needed,
                // but simplicity suggests limiting undo to current turn.
                // Resetting match-level undo history on player switch to avoid confusion:
                setHistory([]); 
            }, 500);
        } else {
            setTurnDartsThrown(nextDartsThrown);
        }
    };

    const handleUndo = () => {
        if (history.length === 0) return;
        const lastState = history[history.length - 1];
        setStates(lastState);
        setHistory(prev => prev.slice(0, -1));
        if (turnDartsThrown > 0) setTurnDartsThrown(prev => prev - 1);
    };

    // --- RENDER ---

    if (winnerId) {
        const winner = states.find(p => p.id === winnerId)!;
        return (
            <div className="h-screen bg-black text-white flex flex-col items-center justify-center p-6 animate-in fade-in duration-500">
                 <h1 className="text-6xl font-black italic text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-600 mb-4 text-center drop-shadow-[0_0_15px_rgba(234,88,12,0.5)]">
                     VAINQUEUR
                 </h1>
                 <div className="text-4xl font-bold text-white mb-2 uppercase text-center">
                     {winner.name}
                 </div>
                 <div className="text-xl text-gray-400 font-mono mb-12 uppercase tracking-widest">
                     Score Final: {winner.score}
                 </div>
                 <Button onClick={() => onFinish(states)} size="lg" className="w-full max-w-xs h-20 text-2xl uppercase shadow-lg shadow-orange-900/40">
                     Voir les Stats ➔
                 </Button>
            </div>
        );
    }

    return (
        <div className="h-screen bg-gradient-to-br from-gray-900 to-black text-white flex flex-col overflow-hidden">
             {/* Header */}
            <div className="h-14 shrink-0 bg-gray-900 border-b border-gray-800 flex justify-between items-center px-4 z-20">
                <div className="font-black italic text-lg">
                    <span className="text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
                        CRICKET
                    </span>
                </div>
                <div className="flex gap-2">
                    <div className="flex gap-1 items-center mr-4">
                         {[1, 2, 3].map(i => (
                            <div key={i} className={`w-3 h-3 rounded-full border border-gray-600 ${i <= turnDartsThrown ? 'bg-orange-500 shadow-[0_0_8px_rgba(249,115,22,0.8)] border-orange-500' : 'bg-transparent'}`}></div>
                         ))}
                    </div>
                    <button onClick={() => setShowExitConfirm(true)} className="text-gray-500 hover:text-white px-2">✕</button>
                </div>
            </div>

            {/* Scoreboard */}
            <CricketScoreboard players={states} currentPlayerId={currentPlayer.id} />

            {/* Keypad Area */}
            <div className="h-[45vh] shrink-0 z-30">
                <CricketKeypad 
                    onHit={handleHit} 
                    onMiss={handleMiss} 
                    onUndo={handleUndo} 
                    canUndo={history.length > 0} 
                />
            </div>

            {/* Exit Confirmation */}
            {showExitConfirm && (
                <div className="fixed inset-0 z-[60] bg-black/90 backdrop-blur-sm flex items-center justify-center p-4">
                    <div className="bg-gray-900 rounded-xl p-6 w-full max-w-sm text-center border border-gray-700 shadow-2xl">
                        <h3 className="text-2xl font-black text-white mb-2 italic uppercase">Quitter le match ?</h3>
                        <div className="grid grid-cols-2 gap-3 mt-8">
                            <Button variant="secondary" onClick={() => setShowExitConfirm(false)}>NON</Button>
                            <Button variant="danger" onClick={onExit}>OUI</Button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React from 'react';
import { Button } from '../components/ui/Button';
import { CricketPlayerState } from '../types';

interface CricketStatsViewProps {
  results: CricketPlayerState[];
  onHome: () => void;
  onRematch: () => void;
}

export const CricketStatsView: React.FC<CricketStatsViewProps> = ({ results, onHome, onRematch }) => {
  // Sort by winner (highest score usually, but logic in game handles strict win)
  // For display, we just use the order provided or sort by score desc
  const sorted = [...results].sort((a,b) => b.score - a.score);
  const winner = sorted[0];

  return (
    <div className="h-screen bg-gradient-to-br from-gray-900 to-black text-white flex flex-col overflow-hidden">

      {/* HEADER */}
      <div className="shrink-0 pt-8 pb-6 text-center">
         <h1 className="text-4xl md:text-6xl font-black italic text-transparent bg-clip-text bg-gradient-to-br from-orange-500 via-red-500 to-orange-500 drop-shadow-[0_5px_15px_rgba(234,88,12,0.4)]">
            CRICKET MASTER
         </h1>
         <h2 className="text-lg md:text-xl text-gray-400 font-bold uppercase tracking-widest mt-2 px-4">
            Vainqueur: <span className="text-white">{winner.name}</span>
         </h2>
      </div>

      {/* STATS CONTENT */}
      <div className="flex-1 w-full max-w-4xl mx-auto px-4 overflow-y-auto custom-scrollbar mb-4">
         <div className="bg-gray-900/50 rounded-2xl border border-gray-800 p-6 space-y-6 shadow-2xl">

             {sorted.map((p, index) => {
                 const totalMarks = Object.values(p.marks).reduce((a, b) => a + b, 0);
                 const mpr = p.dartsThrown > 0 ? (totalMarks / (p.dartsThrown / 3)).toFixed(2) : "0.00";

                 return (
                    <div key={p.id} className="border-b border-gray-800 pb-4 last:border-0">
                        <div className="flex justify-between items-center mb-3">
                            <div className="flex items-center gap-3">
                                <div className={`w-8 h-8 rounded-full flex items-center justify-center font-black text-sm ${index === 0 ? 'bg-yellow-500 text-black' : 'bg-gray-700 text-gray-400'}`}>
                                    {index + 1}
                                </div>
                                <span className="font-bold text-lg text-white">{p.name}</span>
                            </div>
                            <div className="text-3xl font-black text-orange-500">
                                {p.score} <span className="text-xs text-gray-500 font-normal align-middle">PTS</span>
                            </div>
                        </div>

                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            <StatBox label="Marks Per Round (MPR)" value={mpr} />
                            <StatBox label="Total Marks" value={totalMarks} />
                            <StatBox label="Darts Thrown" value={p.dartsThrown} />
                            <StatBox label="Point Accuracy" value={`${p.dartsThrown > 0 ? ((p.history.filter(h => !h.isMiss && h.pointsScored > 0).length / p.dartsThrown) * 100).toFixed(0) : 0}%`} />
                        </div>
                    </div>
                 );
             })}

         </div>
      </div>

      {/* FOOTER ACTIONS */}
      <div className="shrink-0 w-full max-w-lg mx-auto px-6 pb-8 grid grid-cols-2 gap-4">
        <Button onClick={onRematch} variant="secondary" size="lg" className="w-full border-orange-600 text-orange-500 hover:bg-orange-900/20">
            REVANCHE
        </Button>
        <Button onClick={onHome} variant="primary" size="lg" className="w-full shadow-orange-900/40">
            SORTIE
        </Button>
      </div>
    </div>
  );
};

const StatBox = ({ label, value }: { label: string, value: string | number }) => (
