      title: 'Finish 121',
      desc: 'Checkout practice. Finish 121-170 in 9 darts.',
      active: false,
      color: 'from-violet-600 to-indigo-600'
    },
    {
      id: 'SHANGHAI' as GameType,
      title: 'Shanghai',
      desc: 'Hit Single, Double, Triple of the same number.',
      active: false,
      color: 'from-pink-600 to-rose-600'
    }
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      <div className="flex items-center mb-8">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500 uppercase">
            Select Game
        </h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 max-w-5xl mx-auto w-full">
        {games.map((game) => (
          <button
            key={game.id}
            onClick={() => game.active && onSelect(game.id)}
            className={`
              relative group overflow-hidden rounded-xl p-6 text-left border border-gray-800 transition-all duration-300
              ${game.active ? 'bg-gray-800/40 hover:border-orange-500/50 hover:scale-[1.02] hover:shadow-2xl cursor-pointer' : 'bg-gray-900/20 opacity-70 cursor-not-allowed'}
            `}
          >
            {/* Background Gradient on Hover */}
            <div className={`absolute inset-0 bg-gradient-to-br ${game.color} opacity-0 group-hover:opacity-10 transition-opacity duration-500`}></div>

            <div className="relative z-10">
              <div className="flex justify-between items-start mb-2">
                <h3 className={`text-2xl font-black italic uppercase ${game.active ? 'text-white' : 'text-gray-400'}`}>
                  {game.title}
                </h3>
                {!game.active && (
                   <span className="text-[10px] uppercase font-bold bg-gray-800 text-gray-500 px-2 py-1 rounded border border-gray-700">Coming Soon</span>
                )}
              </div>

              <p className="text-sm text-gray-400 font-medium leading-relaxed">
                {game.desc}
              </p>
            </div>

            {/* Decoration */}
            <div className={`absolute -bottom-4 -right-4 w-24 h-24 rounded-full bg-gradient-to-br ${game.color} blur-2xl opacity-20 group-hover:opacity-30 transition-opacity`}></div>
          </button>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Button } from '../components/ui/Button';
import { GameConfig, Player, InOutRule, MatchMode } from '../types';
import { GameType } from './GameSelectionView';

interface SetupViewProps {
  gameType?: GameType; // Add gameType prop
  onStart: (players: Player[], config: GameConfig) => void;
  onBack: () => void;
}

export const SetupView: React.FC<SetupViewProps> = ({ onStart, onBack, gameType = 'X01' }) => {
  const [startingScore, setStartingScore] = useState(501);
  const [customScoreStr, setCustomScoreStr] = useState('170');

  const [matchMode, setMatchMode] = useState<MatchMode>('LEGS');
  const [legsToWin, setLegsToWin] = useState(3);
  const [setsToWin, setSetsToWin] = useState(3);

  // New: Doubles Mode
  const [isDoubles, setIsDoubles] = useState(false);
  const [enableVoice, setEnableVoice] = useState(false);

  // Player State
  const [playerNames, setPlayerNames] = useState<string[]>(['Player 1', 'Player 2']);

  // Doubles specific state
  const [team1Names, setTeam1Names] = useState(['Player 1', 'Player 2']);
  const [team2Names, setTeam2Names] = useState(['Player 3', 'Player 4']);

  // Defaults: Double Out, Open In
  const [checkOut, setCheckOut] = useState<InOutRule>('Double');
  const [checkIn, setCheckIn] = useState<InOutRule>('Open');

  // Solo Player Count
  const updatePlayerCount = (delta: number) => {
    const currentCount = playerNames.length;
    const newCount = Math.max(1, Math.min(4, currentCount + delta));

    if (newCount === currentCount) return;

    setPlayerNames(prev => {
      if (newCount > prev.length) {
        return [...prev, `Player ${newCount}`];
      } else {
        return prev.slice(0, newCount);
      }
    });
  };

  const updatePlayerName = (index: number, name: string) => {
    const newNames = [...playerNames];
    newNames[index] = name;
    setPlayerNames(newNames);
  };

  const updateTeamName = (team: 1 | 2, index: number, name: string) => {
      if (team === 1) {
          const n = [...team1Names];
          n[index] = name;
          setTeam1Names(n);
      } else {
          const n = [...team2Names];
          n[index] = name;
          setTeam2Names(n);
      }
  }

  const handleStart = () => {
    const safeStartingScore = startingScore > 0 ? startingScore : 501;
    let players: Player[] = [];

    if (isDoubles) {
        const p1 = { id: 't1p1', name: team1Names[0].trim() || 'Player 1', teamId: 'team1' };
        const p2 = { id: 't1p2', name: team1Names[1].trim() || 'Player 2', teamId: 'team1' };
        const p3 = { id: 't2p1', name: team2Names[0].trim() || 'Player 3', teamId: 'team2' };
        const p4 = { id: 't2p2', name: team2Names[1].trim() || 'Player 4', teamId: 'team2' };
        players = [p1, p2, p3, p4];
    } else {
        players = playerNames.map((name, i) => ({
            id: `p${i+1}`,
            name: name.trim() || `Player ${i+1}`,
            teamId: `p${i+1}` 
        }));
    }

    const config: GameConfig = {
      startingScore: safeStartingScore,
      checkIn,
      checkOut,
      matchMode,
      legsToWin, 
      setsToWin,
      isDoubles,
      enableVoice
    };

    onStart(players, config);
  };

  const activeOptionClass = "bg-gradient-to-r from-orange-600 to-red-600 text-white border-transparent shadow-[0_0_10px_rgba(234,88,12,0.3)]";
  const inactiveOptionClass = "bg-gray-800 border-gray-700 text-gray-400 hover:border-orange-500/50 hover:text-gray-200";

  const getRuleDescription = (type: 'in' | 'out', rule: InOutRule) => {
     if (type === 'out') {
         switch(rule) {
             case 'Open': return "Finish on any segment.";
             case 'Double': return "Standard: Finish on a Double or Bullseye.";
             case 'Master': return "Finish on a Double, Triple or Bullseye.";
         }
     } else {
         switch(rule) {
             case 'Open': return "Start scoring immediately.";
             case 'Double': return "Must hit a Double to start.";
             case 'Master': return "Must hit a Double or Triple to start.";
         }
     }
  };

  const presets = [301, 501, 701, 1001];
  const isPresetSelected = presets.includes(startingScore);
  const isCustomActive = !isPresetSelected || startingScore === parseInt(customScoreStr || '0');

  const handleCustomFocus = () => {
      const val = parseInt(customScoreStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  const handleCustomChange = (valStr: string) => {
      setCustomScoreStr(valStr);
      const val = parseInt(valStr);
      if (!isNaN(val)) setStartingScore(val);
  };

  const getTitle = () => {
      if (gameType === 'CLOCK') return 'ROUND THE WORLD';
      if (gameType === '180') return '180 ATTACK';
      if (gameType === 'CRICKET') return 'CRICKET SETUP';
      return 'MATCH SETUP';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-black text-white p-6 flex flex-col">
      <div className="flex items-center mb-6">
        <Button variant="ghost" onClick={onBack} size="sm">← Back</Button>
        <h2 className="text-2xl font-black italic ml-4 text-transparent bg-clip-text bg-gradient-to-r from-orange-500 to-red-500">
            {getTitle()}
        </h2>
      </div>

      <div className="flex-1 space-y-6 max-w-md mx-auto w-full overflow-y-auto pb-4 custom-scrollbar">

        {/* Score Selection - ONLY FOR X01 */}
        {gameType === 'X01' && (
            <section>
            <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Starting Score</label>
            <div className="grid grid-cols-4 gap-2 mb-3">
                {presets.map(score => (
                <button
                    key={score}
                    onClick={() => setStartingScore(score)}
                    className={`py-3 rounded font-black border transition-all duration-200 ${startingScore === score ? activeOptionClass : inactiveOptionClass}`}
                >
                    {score}
                </button>
                ))}
            </div>

            <div 
                className={`flex items-center space-x-3 p-3 rounded-lg border transition-all duration-200 ${isCustomActive && !presets.includes(startingScore) ? 'bg-gray-800 border-orange-500 shadow-[0_0_10px_rgba(234,88,12,0.15)]' : 'bg-gray-800/30 border-gray-700'}`}
                onClick={handleCustomFocus}
            >
                <span className={`text-xs font-bold uppercase tracking-wider whitespace-nowrap ${isCustomActive && !presets.includes(startingScore) ? 'text-orange-500' : 'text-gray-500'}`}>Custom Score</span>
                <input 
                    type="number" 
                    min="1"
                    max="9999"
                    value={customScoreStr}
                    onChange={(e) => handleCustomChange(e.target.value)}
                    onFocus={handleCustomFocus}
                    className={`w-full bg-transparent text-right font-mono font-black text-xl focus:outline-none focus:text-orange-500 ${isCustomActive && !presets.includes(startingScore) ? 'text-white' : 'text-gray-500'}`}
                    placeholder="Enter score..."
                />
            </div>
            </section>
        )}

        {/* Players Configuration */}
        <section>
            <div className="flex justify-between items-center mb-2">
                <label className="block text-orange-500 text-xs font-bold uppercase tracking-widest">Players</label>
                {/* Doubles only for X01 currently */}
                {gameType === 'X01' && (
                    <div className="flex bg-gray-800 rounded p-1">
                        <button onClick={() => setIsDoubles(false)} className={`px-3 py-1 text-xs font-bold rounded ${!isDoubles ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>Solo</button>
                        <button onClick={() => setIsDoubles(true)} className={`px-3 py-1 text-xs font-bold rounded ${isDoubles ? 'bg-gray-600 text-white' : 'text-gray-500'}`}>Doubles (2v2)</button>
                    </div>
                )}
            </div>

            {!isDoubles ? (
                <>
                    <div className="flex items-center space-x-4 bg-gray-800/50 p-2 rounded-lg mb-4 border border-gray-700">
                        <button onClick={() => updatePlayerCount(-1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">-</button>
                        <span className="flex-1 text-center font-black text-2xl text-white">{playerNames.length}</span>
                        <button onClick={() => updatePlayerCount(1)} className="w-10 h-10 bg-gray-700 hover:bg-gray-600 rounded text-xl font-bold transition-colors">+</button>
                    </div>
                    <div className="space-y-2">
                        {playerNames.map((name, index) => (
                        <div key={index} className="flex items-center group">
                            <span className="w-8 text-gray-500 text-xs font-bold group-hover:text-orange-500 transition-colors">#{index + 1}</span>
                            <input
                            type="text"
                            value={name}
                            onChange={(e) => updatePlayerName(index, e.target.value)}
                            onFocus={(e) => e.target.select()}
                            className="flex-1 bg-gray-800 border border-gray-700 text-white px-3 py-3 rounded font-bold focus:outline-none focus:border-orange-500 focus:ring-1 focus:ring-orange-500 transition-all"
                            placeholder={`Player ${index + 1}`}
                            />
                        </div>
                        ))}
                    </div>
                </>
            ) : (
                <div className="space-y-4">
                    <div className="bg-gray-800/30 p-3 rounded border border-gray-700">
                        <div className="text-xs text-orange-500 font-bold uppercase mb-2">Team 1</div>
                        <div className="space-y-2">
                            <input value={team1Names[0]} onChange={(e) => updateTeamName(1, 0, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 1" />
                            <input value={team1Names[1]} onChange={(e) => updateTeamName(1, 1, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 2" />
                        </div>
                    </div>
                    <div className="bg-gray-800/30 p-3 rounded border border-gray-700">
                        <div className="text-xs text-orange-500 font-bold uppercase mb-2">Team 2</div>
                        <div className="space-y-2">
                            <input value={team2Names[0]} onChange={(e) => updateTeamName(2, 0, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 3" />
                            <input value={team2Names[1]} onChange={(e) => updateTeamName(2, 1, e.target.value)} className="w-full bg-gray-800 border border-gray-600 text-white px-2 py-2 rounded text-sm" placeholder="Player 4" />
                        </div>
                    </div>
                </div>
            )}
        </section>

        {/* Format - ONLY FOR X01 */}
        {gameType === 'X01' && (
            <section>
            <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Match Format</label>

            <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-4">
                <button onClick={() => setMatchMode('LEGS')} className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all ${matchMode === 'LEGS' ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                    Legs
                </button>
                <button onClick={() => setMatchMode('SETS')} className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all ${matchMode === 'SETS' ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                    Sets
                </button>
            </div>

            <div className="bg-gray-800/30 p-4 rounded-lg border border-gray-700 space-y-4">
                {matchMode === 'LEGS' ? (
                    <div>
                    <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Legs to Win Match</label>
                    <div className="grid grid-cols-5 gap-2">
                        {[1, 3, 5, 7, 9].map(num => (
                            <button key={num} onClick={() => setLegsToWin(num)} className={`py-2 rounded font-bold text-sm border ${legsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                                {num}
                            </button>
                        ))}
                    </div>
                    </div>
                ) : (
                    <>
                    <div>
                        <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Sets to Win Match</label>
                        <div className="grid grid-cols-4 gap-2">
                            {[1, 3, 5, 7].map(num => (
                                <button key={num} onClick={() => setSetsToWin(num)} className={`py-2 rounded font-bold text-sm border ${setsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                                    {num}
                                </button>
                            ))}
                        </div>
                    </div>
                    <div>
                        <label className="text-gray-400 text-[10px] font-bold uppercase mb-2 block">Legs to Win a Set</label>
                        <div className="grid grid-cols-4 gap-2">
                            {[3, 5].map(num => (
                                <button key={num} onClick={() => setLegsToWin(num)} className={`py-2 rounded font-bold text-sm border ${legsToWin === num ? 'bg-orange-600 border-transparent text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>
                                    {num}
                                </button>
                            ))}
                        </div>
                    </div>
                    </>
                )}
            </div>
            </section>
        )}

        {/* In / Out Rules - ONLY FOR X01 */}
        {gameType === 'X01' && (
            <section className="grid grid-cols-1 gap-6">
            <div>
                <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Check In Rule</label>
                <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                    {(['Open', 'Double', 'Master'] as const).map(rule => (
                        <button
                        key={rule}
                        onClick={() => setCheckIn(rule)}
                        className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkIn === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                        >
                        {rule} In
                        </button>
                    ))}
                </div>
                <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('in', checkIn)}</p>
            </div>

            <div>
                <label className="block text-orange-500 mb-2 text-xs font-bold uppercase tracking-widest">Checkout Rule</label>
                <div className="flex p-1 bg-gray-800 rounded-lg border border-gray-700 mb-2">
                    {(['Open', 'Double', 'Master'] as const).map(rule => (
                        <button
                        key={rule}
                        onClick={() => setCheckOut(rule)}
                        className={`flex-1 py-2 text-xs font-bold uppercase tracking-wider rounded transition-all duration-200 ${checkOut === rule ? 'bg-gray-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}
                        >
                        {rule} Out
                        </button>
                    ))}
                </div>
                <p className="text-[10px] text-gray-500 italic px-1 h-3">{getRuleDescription('out', checkOut)}</p>
            </div>
            </section>
        )}

      </div>

      {/* FOOTER ACTIONS - Moved outside flex-1 for sticky bottom */}
      <div className="mt-4">
        <Button onClick={handleStart} className="w-full py-5 text-2xl shadow-orange-900/20">GAME ON</Button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HomeView } from './views/HomeView';
import { SetupView } from './views/SetupView';
import { MatchView } from './views/MatchView';
import { StatsView } from './views/StatsView';
import { AuthView } from './views/AuthView';
import { DashboardView } from './views/DashboardView';
import { ProfileView } from './views/ProfileView';
import { HistoryView } from './views/HistoryView'; 
import { MyStatsView } from './views/MyStatsView'; 
import { SettingsView } from './views/SettingsView';
import { GameSelectionView, GameType } from './views/GameSelectionView';
import { ClockGameView } from './views/ClockGameView';
import { ClockStatsView } from './views/ClockStatsView';
import { CricketGameView } from './views/CricketGameView';
import { CricketStatsView } from './views/CricketStatsView';
import { GameConfig, Player, MatchState, ClockPlayerState, CricketPlayerState } from './types';
import { createMatch } from './utils/gameLogic';
import { enterFullScreen, exitFullScreen } from './utils/uiUtils';
import { supabase, saveMatchToHistory } from './lib/supabase';

type AppScreen = 'HOME' | 'AUTH' | 'DASHBOARD' | 'PROFILE' | 'HISTORY' | 'MY_STATS' | 'SETTINGS' | 'GAME_SELECTION' | 'SETUP' | 'MATCH' | 'STATS' | 'CLOCK_GAME' | 'CLOCK_STATS' | 'CRICKET_GAME' | 'CRICKET_STATS';

export const App: React.FC = () => {
  const [screen, setScreen] = useState<AppScreen>('HOME');
  const [currentMatch, setCurrentMatch] = useState<MatchState | null>(null);
  const [matchWinner, setMatchWinner] = useState<string>('');
  const [user, setUser] = useState<any>(null);

  // State for Clock/180 results
  const [clockResults, setClockResults] = useState<ClockPlayerState[]>([]);

  // State for Cricket results
  const [cricketResults, setCricketResults] = useState<CricketPlayerState[]>([]);

  // Check active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (_event === 'SIGNED_OUT') {
          setScreen('HOME');
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  const [selectedGameType, setSelectedGameType] = useState<GameType>('X01');

  const handleQuickGame = () => {
    setScreen('GAME_SELECTION');
  };

  const handleGameSelect = (type: GameType) => {
    setSelectedGameType(type);
    if (type === 'X01' || type === 'CLOCK' || type === '180' || type === 'CRICKET') {
      setScreen('SETUP');
    } else {
      alert(`Mode ${type} is coming soon!`);
    }
  };

  const handleStartSetup = (players: Player[], config: GameConfig) => {
    enterFullScreen();
    const match = createMatch(players, config);
    setCurrentMatch(match);

    if (selectedGameType === 'CLOCK' || selectedGameType === '180') {
      setScreen('CLOCK_GAME');
    } else if (selectedGameType === 'CRICKET') {
      setScreen('CRICKET_GAME');
    } else {
      setScreen('MATCH');
    }
  };

  const handleMatchFinish = (winnerId: string) => {
    exitFullScreen();
    setMatchWinner(winnerId);
    setScreen('STATS');
  };

  const handleMatchFinishWithData = (winnerId: string, finalMatch: MatchState) => {
      exitFullScreen();
      setMatchWinner(winnerId);
      setCurrentMatch(finalMatch);

      if (user) {
          saveMatchToHistory(user.id, finalMatch);
      }

      setScreen('STATS');
  }

  // Handler for Clock/180 games
  const handleClockFinish = (results: ClockPlayerState[]) => {
      exitFullScreen();
      setClockResults(results);
      setScreen('CLOCK_STATS');
  };

  // Handler for Cricket games
  const handleCricketFinish = (results: CricketPlayerState[]) => {
      exitFullScreen();
      setCricketResults(results);
      // NOTE: Saving to DB not yet implemented for Cricket
      setScreen('CRICKET_STATS');
  };

  const handleExitMatch = () => {
    exitFullScreen();
    setScreen(user ? 'DASHBOARD' : 'HOME');
    setCurrentMatch(null);
  };

  const handleRematch = () => {
      if (!currentMatch) return;

      const newMatch = createMatch(currentMatch.players, currentMatch.config);
      setCurrentMatch(newMatch);
      enterFullScreen();

      if (selectedGameType === 'CLOCK' || selectedGameType === '180') {
        setScreen('CLOCK_GAME');
      } else if (selectedGameType === 'CRICKET') {
        setScreen('CRICKET_GAME');
      } else {
        setScreen('MATCH');
      }
  };

  const handleLogout = async () => {
      await supabase.auth.signOut();
      setUser(null);
      setScreen('HOME');
  };

  return (
    <div className="antialiased font-sans bg-black h-full">
      {screen === 'HOME' && (
        <HomeView 
          onQuickGame={handleQuickGame} 
          onLogin={() => setScreen(user ? 'DASHBOARD' : 'AUTH')} 
          onSettings={() => setScreen('SETTINGS')}
        />
      )}

      {screen === 'AUTH' && (
        <AuthView 
          onBack={() => setScreen('HOME')}
          onLoginSuccess={(loggedInUser) => {
            setUser(loggedInUser);
            setScreen('DASHBOARD');
          }}
        />
      )}

      {screen === 'DASHBOARD' && user && (
          <DashboardView 
              user={user}
              onPlay={() => setScreen('GAME_SELECTION')}
              onHistory={() => setScreen('HISTORY')}
              onStats={() => setScreen('MY_STATS')}
              onProfile={() => setScreen('PROFILE')}
              onSettings={() => setScreen('SETTINGS')}
              onLogout={handleLogout}
          />
      )}

      {screen === 'PROFILE' && user && (
          <ProfileView 
              user={user}
              onBack={() => setScreen('DASHBOARD')}
              onUpdateUser={(updatedUser) => setUser(updatedUser)}
          />
      )}

      {screen === 'HISTORY' && user && (
          <HistoryView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'MY_STATS' && user && (
          <MyStatsView 
             user={user}
             onBack={() => setScreen('DASHBOARD')}
          />
      )}

      {screen === 'SETTINGS' && (
          <SettingsView 
             onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
          />
      )}

      {screen === 'GAME_SELECTION' && (
        <GameSelectionView 
          onSelect={handleGameSelect}
          onBack={() => setScreen(user ? 'DASHBOARD' : 'HOME')}
        />
      )}

      {screen === 'SETUP' && (
        <SetupView 
          gameType={selectedGameType}
          onStart={handleStartSetup} 
          onBack={() => setScreen('GAME_SELECTION')} 
        />
      )}

      {screen === 'MATCH' && currentMatch && (
        <MatchView 
          initialMatch={currentMatch} 
          onFinish={handleMatchFinish}
          onFinishWithState={handleMatchFinishWithData}
          onExit={handleExitMatch}
        />
      )}

      {screen === 'CLOCK_GAME' && currentMatch && (
        <ClockGameView 
          players={currentMatch.players}
          mode={selectedGameType === '180' ? '180' : 'STANDARD'}
          onExit={handleExitMatch}
          onFinish={handleClockFinish}
        />
      )}

      {screen === 'CLOCK_STATS' && (
          <ClockStatsView 
              results={clockResults}
              mode={selectedGameType === '180' ? '180' : 'STANDARD'}
              onHome={handleExitMatch}
              onRematch={handleRematch}
          />
      )}

      {screen === 'CRICKET_GAME' && currentMatch && (
          <CricketGameView
              players={currentMatch.players}
              onExit={handleExitMatch}
              onFinish={handleCricketFinish}
          />
      )}

      {screen === 'CRICKET_STATS' && (
          <CricketStatsView
              results={cricketResults}
              onHome={handleExitMatch}
              onRematch={handleRematch}
          />
      )}

      {screen === 'STATS' && currentMatch && (
        <StatsView 
          winnerId={matchWinner} 
          onHome={handleExitMatch}
          onRematch={handleRematch}
          match={currentMatch}
        />
      )}
    </div>
  );
};

import { CricketPlayerState, CricketTarget, Player } from '../types';

export const CRICKET_TARGETS: CricketTarget[] = [20, 19, 18, 17, 16, 15, 25];

export const initCricketState = (players: Player[]): CricketPlayerState[] => {
    return players.map(p => ({
        id: p.id,
        name: p.name,
        score: 0,
        marks: {
            20: 0, 19: 0, 18: 0, 17: 0, 16: 0, 15: 0, 25: 0
        },
        dartsThrown: 0,
        history: []
    }));
};

export const isNumberClosedGlobally = (states: CricketPlayerState[], target: CricketTarget): boolean => {
    // A number is closed globally if ALL players have 3 marks on it
    return states.every(p => p.marks[target] >= 3);
};

export const processCricketHit = (
    states: CricketPlayerState[],
    playerId: string,
    target: CricketTarget,
    multiplier: 1 | 2 | 3
): { newStates: CricketPlayerState[], pointsScored: number, isClosedByHit: boolean } => {

    const pIdx = states.findIndex(p => p.id === playerId);
    if (pIdx === -1) return { newStates: states, pointsScored: 0, isClosedByHit: false };

    // Deep copy to avoid mutation
    const newStates = JSON.parse(JSON.stringify(states));
    const player = newStates[pIdx];

    const currentMarks = player.marks[target];
    const newTotalMarks = currentMarks + multiplier;

    let pointsScored = 0;
    let marksToAdd: number = multiplier;
    let isClosedByHit = false;

    // Logic:
    // 1. Fill marks up to 3.
    // 2. If > 3, check if opponents have closed it.
    // 3. If opponents NOT closed, add (surplus * targetValue) to score.

    if (currentMarks < 3) {
        const needed = 3 - currentMarks;
        if (multiplier >= needed) {
            // We closed it this turn
            player.marks[target] = 3;
            marksToAdd = multiplier - needed; // Remaining marks for scoring
            isClosedByHit = true;
        } else {
            // Just adding marks, not closed yet
            player.marks[target] += multiplier;
            marksToAdd = 0; 
        }
    } else {
        // Already closed by player, all multiplier is for potential scoring
        marksToAdd = multiplier;
    }

    // Scoring Logic (Strict Rules)
    // Points are scored if the player has closed the number (which is true if marksToAdd > 0 here)
    // AND at least one opponent has NOT closed it.
    if (marksToAdd > 0) {
        const isClosedByAll = newStates.every((p: CricketPlayerState) => p.marks[target] >= 3);

        if (!isClosedByAll) {
            pointsScored = marksToAdd * target;
            player.score += pointsScored;
        }
    }

    player.dartsThrown += 1;
    player.history.push({
        target,
        multiplier,
        isMiss: false,
        pointsScored
    });

    return { newStates, pointsScored, isClosedByHit };
};

export const checkCricketWin = (states: CricketPlayerState[]): string | null => {
    // Win condition:
    // 1. Player has closed all numbers (all marks >= 3)
    // 2. Player has the highest (or tied highest) score

    // Sort by score descending to easily check lead
    const sortedByScore = [...states].sort((a,b) => b.score - a.score);
    const highestScore = sortedByScore[0].score;

    for (const player of states) {
        const allClosed = CRICKET_TARGETS.every(t => player.marks[t] >= 3);
        const hasScoreLead = player.score >= highestScore;

        if (allClosed && hasScoreLead) {
            return player.id;
        }
    }

    return null;
};

