};

// Mots de remplissage à ignorer AVANT la validation stricte
const FILLER_WORDS = new Set([
  "j", "ai", "fait", "mis", "je", "fais", "c", "est", "un", "une", "il", "y", "a",
  "et", "sur", "le", "la", "les", "de", "du", "pour", "alors", "bon", "bah", "mets", 
