                 <button onClick={() => setMatch(undoTurn(match))} className="text-[10px] font-bold text-gray-500 uppercase hover:text-white transition-colors flex items-center gap-1 p-2">
                    <span>Undo</span> <span className="text-lg">↶</span>
                 </button>
