    if (!userId) return [];

    const { data, error } = await supabase
        .from('matches')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: false }); // Plus récent en premier

    if (error) {
        console.error("Error fetching matches:", error);
        return [];
    }

    return data || [];
};

